# precompute adjacency
adj=[[] for _ in range(size)]
for r in range(N):
    for c in range(N):
        i=r*N+c
        for dr,dc in moves:
            nr, nc = r+dr, c+dc
            if 0<=nr<N and 0<=nc<N:
                adj[i].append(nr*N+nc)
# fixed positions dict index->value
fixed={3:17,6:24,17:30,19:6,29:25,32:21,34:23}
solution=[-1]*size
solution[0]=0
used=[False]*size
used[0]=True
