for idx,val in fixed.items():
    if idx==0:
        if val!=0:
            print('conflict')
            sys.exit()
    # will set later

def backtrack(pos):
    if pos==size:
        return True
    # if this position is fixed, must use that value
    if pos in fixed:
        cand=[fixed[pos]]
    else:
        # candidates are unused neighbors of previous cell
        prev=solution[pos-1]
        cand=[v for v in adj[prev] if not used[v]]
    # heuristic: sort by degree (Warnsdorff)
    def deg(v):
        return sum(1 for nb in adj[v] if not used[nb])
    cand.sort(key=deg)
    for v in cand:
        if used[v]: continue
        solution[pos]=v
        used[v]=True
        if backtrack(pos+1):
            return True
        used[v]=False
        solution[pos]=-1
    return False

