import itertools, sys
nums=range(1,19)
target=57
for comb in itertools.combinations(nums,6):
    if sum(comb)==target:
        remaining=[x for x in nums if x not in comb]
        for comb2 in itertools.combinations(remaining,6):
            if sum(comb2)==target:
                comb3=tuple(x for x in remaining if x not in comb2)
                if sum(comb3)==target:
                    print(comb, comb2, comb3)
                    sys.exit()

